def transform(grid):
    """Count upward/downward T tetrominoes and encode each count in a 3x3 tile."""
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {'up': 0, 'down': 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (x + dx, y + dy)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        stack.append(p)
            if len(cells) != 4:
                continue
            rows = {}
            for x, _ in cells:
                rows[x] = rows.get(x, 0) + 1
            top, bottom = min(rows), max(rows)
            if rows[top] == 1 and rows[bottom] == 3:
                counts['up'] += 1
            elif rows[top] == 3 and rows[bottom] == 1:
                counts['down'] += 1

    out = [[0] * 6 for _ in range(3)]
    # A count is shown as corner markers in reading order: TL, BL, TR, BR.
    corners = ((0, 0), (2, 0), (0, 2), (2, 2))
    for color, col_offset, n in ((3, 0, counts['up']), (1, 3, counts['down'])):
        for r, c in corners[:min(n, 4)]:
            out[r][col_offset + c] = color
    return out
